function captureV09RequestBody(request,_response,bytes){if(request.method==='POST'&&request.originalUrl===V09_ASSESS_POST)request.v09OriginalBody=Buffer.from(bytes);}
function observeOriginalV09Json(request,response,captures){const url=new URL(request.originalUrl,'http://fixture.invalid'),post=request.method==='POST'&&url.pathname===V09_ASSESS_POST,get=request.method==='GET'&&V09_ASSESS_GET.test(url.pathname);if(!post&&!get)return;const raw=request.v09OriginalBody,event={method:request.method,url:request.originalUrl,body:post?structuredClone(request.body):null,requestBytes:post&&Buffer.isBuffer(raw)?Buffer.from(raw):null,requestSha256:post&&Buffer.isBuffer(raw)?digest(raw):null,status:null,contentType:null,complete:false,finished:false,closed:false,captureTruncated:false,captureError:null,chunks:[],bytes:Buffer.alloc(0),responseSha256:null};captures.push(event);let size=0;const retain=(chunk,encoding)=>{if(chunk==null||typeof chunk==='function')return;try{if(typeof chunk!=='string'&&!Buffer.isBuffer(chunk)&&!(chunk instanceof Uint8Array)){event.captureError='INVALID_V09_JSON_CHUNK';return;}const bytes=typeof chunk==='string'?Buffer.from(chunk,typeof encoding==='string'?encoding:'utf8'):Buffer.from(chunk);size+=bytes.length;if(size>131072){event.captureTruncated=true;return;}event.chunks.push(bytes);}catch{event.captureError='V09_JSON_CHUNK_CAPTURE_UNAVAILABLE';}};const write=response.write,end=response.end;response.write=function(...args){retain(args[0],args[1]);return write.apply(this,args);};response.end=function(...args){retain(args[0],args[1]);return end.apply(this,args);};const snapshot=()=>{event.status=response.statusCode;event.contentType=response.getHeader('content-type')??null;event.bytes=Buffer.concat(event.chunks);event.responseSha256=digest(event.bytes);};response.once('finish',()=>{event.finished=true;snapshot();event.complete=response.writableFinished===true&&!event.captureTruncated&&!event.captureError;});response.once('close',()=>{event.closed=true;if(!event.finished){snapshot();event.complete=false;}});return event;}
function validateOriginalV09Json(event,request,wire){assert.equal(wire.request(),request);const url=new URL(request.url()),post=request.method()==='POST'&&url.pathname===V09_ASSESS_POST,get=request.method()==='GET'&&V09_ASSESS_GET.test(url.pathname);assert(post||get);assert.equal(event.method,request.method());assert.equal(event.url,url.pathname+url.search);if(post){const bytes=Buffer.from(request.postData(),'utf8');assert.deepEqual(event.requestBytes,bytes);assert.equal(event.requestSha256,digest(bytes));assert.deepEqual(event.body,JSON.parse(bytes));}else{assert.equal(event.body,null);assert.equal(event.requestBytes,null);assert.equal(event.requestSha256,null);}assert.equal(event.status,wire.status());assert.equal(event.contentType,wire.headers()['content-type']);assert.equal(event.contentType.split(';')[0].trim().toLowerCase(),'application/json');assert.equal(event.finished,true);assert.equal(event.complete,true);assert.equal(event.captureTruncated,false);assert.equal(event.captureError,null);assert.ok(event.bytes.length>0&&event.bytes.length<=131072);assert.equal(event.responseSha256,digest(event.bytes));return JSON.parse(event.bytes.toString('utf8'));}
async function readOriginalV09Json(captures,request,wire,timeout=120000){const url=new URL(request.url()),exactUrl=url.pathname+url.search,requestHash=request.method()==='POST'?digest(Buffer.from(request.postData(),'utf8')):null,deadline=Date.now()+timeout;while(Date.now()<deadline){const rows=captures.filter(event=>event.method===request.method()&&event.url===exactUrl&&event.requestSha256===requestHash);assert.ok(rows.length<=1);if(rows[0]?.finished||rows[0]?.closed||rows[0]?.captureError)return validateOriginalV09Json(rows[0],request,wire);await new Promise(resolve=>setTimeout(resolve,10));}throw Error('Original V09 JSON server capture did not finish');}
const exact=(value,keys)=>value&&Object.getPrototypeOf(value)===Object.prototype&&Object.keys(value).sort().join(',')===[...keys].sort().join(',');
function assertReference(value,stage){assert(exact(value,['stage','requestId','sourceSessionId','sourceRequestId','sendOperationId','messageId','startedAt']));assert.equal(value.stage,stage);for(const key of ['requestId','sourceSessionId','sourceRequestId','sendOperationId'])assert.match(value[key],UUID);assert.equal(new Set([value.requestId,value.sourceSessionId,value.sourceRequestId,value.sendOperationId]).size,4);assert(Number.isSafeInteger(value.messageId)&&value.messageId>0);assert(Number.isSafeInteger(value.startedAt)&&value.startedAt>0);return value;}
async function waitForAcknowledgedHtmlReference(read,expected,{timeout=30000,interval=10}={}){assert.equal(typeof read,'function');assert(expected&&UUID.test(expected.sourceSessionId)&&UUID.test(expected.sourceRequestId)&&UUID.test(expected.sendOperationId)&&Number.isSafeInteger(expected.messageId)&&expected.messageId>0);assert(Number.isSafeInteger(timeout)&&timeout>0&&Number.isSafeInteger(interval)&&interval>0);const deadline=Date.now()+timeout;while(Date.now()<deadline){const value=await read();if(value!==null){const ready=assertReference(value,'ready');for(const key of ['sourceSessionId','sourceRequestId','sendOperationId','messageId'])assert.equal(ready[key],expected[key]);return ready;}await new Promise(resolve=>setTimeout(resolve,interval));}throw Error('Acknowledged V09 HTML assessment reference unavailable');}
async function runV09FixedGuardFlow({actions,username,recipientId,subject,body}={}){
 assert(username&&Number.isSafeInteger(recipientId)&&recipientId>0&&typeof subject==='string'&&subject&&typeof body==='string'&&body);for(const key of ['sendChat','selectChoice','confirmSend','readHtmlReference','openOwnedInbox','inspectLearnerElementState','assessHtml'])assert.equal(typeof actions?.[key],'function',key);
 const discovery=await actions.sendChat(`Find the mail recipient named "${username}".`),cards=discovery.receipt?.cards?.filter(row=>row.kind==='merchant_mail_recipient'&&row.title===username);assert.equal(cards?.length,1);await actions.selectChoice(`Compose message to ${username}`);
 const chat=await actions.sendChat(`Send the selected recipient a message with subject exactly "${subject}" and body exactly:\n${body}`);assert.equal(chat.receipt?.hops?.at(-1)?.tool,'merchant.mail_send_prepare');assert.deepEqual(chat.receipt.hops.at(-1).params,{choiceId:cards[0].choiceId,subject,body_markdown:body});const proposalId=chat.receipt.mailProposal?.proposalId;assert.match(proposalId,UUID);
 const confirmation=await actions.confirmSend({control:'Send message',chat,proposalId});assert.equal(confirmation.response.value.status,'saved');const messageId=confirmation.response.value.emailId;assert(Number.isSafeInteger(messageId)&&messageId>0);
 const reference=await waitForAcknowledgedHtmlReference(actions.readHtmlReference,{sourceSessionId:chat.body.sessionId,sourceRequestId:chat.body.requestId,sendOperationId:proposalId,messageId});
 const inbox=await actions.openOwnedInbox({control:'Reload',recipientId,sourceEmailId:messageId});assert.equal(inbox.selectedMessage.body_markdown,body);const rendered=await actions.inspectLearnerElementState({title:'V09 learner structural marker',subject,body,messageId});assert.deepEqual(rendered,{source:body,count:0,tag:null,title:null});
 const assessment=await actions.assessHtml({reference});assert.equal(assessment.response.value.status,'ineligible');return Object.freeze({chat,confirmation,reference,inbox,rendered,assessment});
}
function assertV09Receipt(value){assert(exact(value,[...FLAGS,'scope','vulnerableActorCalls','fixedActorCalls','judgeCalls','assessmentPosts','savedAssessmentGets','genuineCredit','errors']));assert.equal(value.scope,SCOPE);for(const flag of FLAGS)if(flag!=='fixtureLocalCandidateAdmission')assert.equal(value[flag],true,flag);assert.equal(typeof value.fixtureLocalCandidateAdmission,'boolean','fixtureLocalCandidateAdmission');for(const key of ['vulnerableActorCalls','fixedActorCalls','judgeCalls','assessmentPosts','savedAssessmentGets','genuineCredit'])assert.equal(typeof value[key],'number');assert.equal(value.vulnerableActorCalls,4);assert.equal(value.fixedActorCalls,4);assert.ok(value.judgeCalls>=1&&value.judgeCalls<=2);assert.equal(value.assessmentPosts,2);assert.equal(value.savedAssessmentGets,1);assert.equal(value.genuineCredit,1);assert.deepEqual(value.errors,[]);return value;}

function createCurrentHtmlReferenceReader({readReadiness,readStorage,objectiveId=OBJECTIVE}={}){assert.equal(typeof readReadiness,'function');assert.equal(typeof readStorage,'function');return async()=>{const response=await readReadiness();assert.equal(response?.status,200);assert.equal(response.value?.objectiveReadiness?.[objectiveId],true);assert.equal(typeof response.value.scopeKey,'string');assert.ok(response.value.scopeKey.length>0&&response.value.scopeKey.length<=512);return readStorage(response.value.scopeKey);};}
function createV09AssessmentActions({base,page,frame,requestFrame,origin,readHtmlReference,reloadForRecovery,readJson,timeout=120000}={}){
 assert(base&&page?.on&&page?.off&&page?.waitForRequest&&page?.waitForResponse&&requestFrame&&new URL(origin).origin===origin);for(const key of ['sendChat','selectChoice','confirmSend','openOwnedInbox'])assert.equal(typeof base[key],'function');for(const fn of [readHtmlReference,reloadForRecovery,readJson])assert.equal(typeof fn,'function');assert(Number.isSafeInteger(timeout)&&timeout>0);const active=()=>typeof frame==='function'?frame():frame;
 let recoveryWire=null;const button=async label=>{const current=active();await current.waitForFunction(text=>[...document.querySelectorAll('button')].filter(node=>node.textContent.trim()===text&&!node.disabled&&node.getClientRects().length).length===1,{timeout:30000},label);const handle=await current.evaluateHandle(text=>{const nodes=[...document.querySelectorAll('button')].filter(node=>node.textContent.trim()===text&&!node.disabled&&node.getClientRects().length);if(nodes.length!==1)return null;const node=nodes[0];node.scrollIntoView({block:'center'});const box=node.getBoundingClientRect(),hit=document.elementFromPoint(box.left+box.width/2,box.top+box.height/2);return hit===node||node.contains(hit)?node:null;},label);const element=handle.asElement();assert(element);try{await element.click();}finally{await handle.dispose();}};
 const predicate=(value,method,path)=>{const request=typeof value.request==='function'?value.request():value,url=new URL(request.url());return request.frame()===requestFrame&&request.method()===method&&url.origin===origin&&url.pathname===path;};
 const capture=async(method,path,click,observeRequest)=>{let duplicate=false,seen=null;const listener=value=>{if(predicate(value,method,path)){if(seen)duplicate=true;else seen=value;}};page.on('request',listener);const requestTask=page.waitForRequest(value=>predicate(value,method,path),{timeout});const responseTask=page.waitForResponse(value=>predicate(value,method,path),{timeout});requestTask.catch(()=>{});responseTask.catch(()=>{});let observationTask;try{const clickTask=Promise.resolve().then(click);clickTask.catch(()=>{});observationTask=requestTask.then(request=>observeRequest?observeRequest(request):null);observationTask.catch(()=>{});const [request,,observation]=await Promise.all([requestTask,clickTask,observationTask]);const response=await responseTask;assert.equal(response.request(),request);assert.equal(duplicate,false);return{request,response:{status:response.status(),value:await readJson(request,response)},observation};}finally{page.off('request',listener);requestTask.catch(()=>{});responseTask.catch(()=>{});observationTask?.catch(()=>{});}};
 return Object.freeze({...base,readHtmlReference,
  async inspectLearnerElementState({title,subject,body}){const value=await active().evaluate((expectedTitle,expectedSubject)=>{const headings=[...document.querySelectorAll('h2')].filter(node=>node.textContent===expectedSubject&&node.getClientRects().length);if(headings.length!==1)return null;const container=headings[0].parentElement?.parentElement;if(!container)return null;const source=[...container.querySelectorAll('details')].find(node=>node.querySelector('summary')?.textContent.trim()==='body_markdown (source)')?.querySelector('pre')?.textContent;const matches=[...container.querySelectorAll('iframe')].filter(node=>node.getAttribute('title')===expectedTitle);return{source,count:matches.length,tag:matches[0]?.localName||null,title:matches[0]?.getAttribute('title')||null};},title,subject);assert(value&&value.source===body);return value;},
  async inspectLearnerElement(input){const value=await this.inspectLearnerElementState(input);assert.deepEqual(value,{source:input.body,count:1,tag:'iframe',title:input.title});return{tag:'iframe',preserved:true,title:input.title};},
  async assessHtml({reference}){const before=assertReference(await readHtmlReference(),'ready');assert.deepEqual(before,reference);const wire=await capture('POST','/api/secureshop/email/html-injection-assessment',()=>button('Assess saved HTML insertion'),()=>readHtmlReference());assert.deepEqual(assertReference(wire.observation,'submitted'),{...reference,stage:'submitted'});assert.deepEqual(JSON.parse(wire.request.postData()),{requestId:reference.requestId,sourceSessionId:reference.sourceSessionId,sourceRequestId:reference.sourceRequestId,sendOperationId:reference.sendOperationId,messageId:reference.messageId});assert.equal(wire.response.status,200);return wire;},
  async reloadForRecovery(input){assert.equal(recoveryWire,null);const reference=assertReference(input.reference,'submitted'),path='/api/secureshop/email/html-injection-assessment/'+[reference.requestId,reference.sourceSessionId,reference.sourceRequestId,reference.sendOperationId,reference.messageId].join('/');recoveryWire=await capture('GET',path,()=>reloadForRecovery(input));assert.equal(recoveryWire.response.status,200);return recoveryWire;},
  async recoverHtml({reference}){assertReference(reference,'submitted');assert(recoveryWire);const expected='/api/secureshop/email/html-injection-assessment/'+[reference.requestId,reference.sourceSessionId,reference.sourceRequestId,reference.sendOperationId,reference.messageId].join('/');assert.equal(new URL(recoveryWire.request.url()).pathname,expected);const wire=recoveryWire;recoveryWire=null;return wire;}
 });
}
async function runV09RenderedQualification({actions,observe,guards,merchant,subject='V09 structural HTML insertion',body=BODY}={}){
 assert(merchant?.username&&merchant?.email&&merchant?.persona?.role==='merchant');for(const key of ['sendChat','selectChoice','confirmSend','openOwnedInbox','inspectLearnerElement','assessHtml','reloadForRecovery','recoverHtml','readHtmlReference'])assert.equal(typeof actions?.[key],'function',key);for(const key of ['readOriginal','readCanonical','finalize'])assert.equal(typeof observe?.[key],'function',key);for(const key of ['fixed','sibling','reset'])assert.equal(typeof guards?.[key],'function',key);
 const discovery=await actions.sendChat(`Find the mail recipient named "${merchant.username}".`);const card=discovery.receipt?.cards?.filter(row=>row.kind==='merchant_mail_recipient'&&row.title===merchant.username);assert.equal(card?.length,1);await actions.selectChoice(`Compose message to ${merchant.username}`);
 const chat=await actions.sendChat(`Send the selected recipient a message with subject exactly "${subject}" and body exactly:\n${body}`);assert.equal(chat.receipt?.hops?.at(-1)?.tool,'merchant.mail_send_prepare');assert.deepEqual(chat.receipt.hops.at(-1).params,{choiceId:card[0].choiceId,subject,body_markdown:body});const proposalId=chat.receipt.mailProposal?.proposalId;assert.match(proposalId,UUID);
 const original=await observe.readOriginal({chat,proposalId,subject,body,choiceId:card[0].choiceId});assert.equal(original.tool,'merchant.mail_send_prepare');assert.equal(original.mocked,false);assert.notEqual(original.fallback,true);
 const confirmation=await actions.confirmSend({control:'Send message',chat,proposalId});assert.equal(confirmation.response.value.status,'saved');const messageId=confirmation.response.value.emailId;assert(Number.isSafeInteger(messageId)&&messageId>0);
 const ready=await waitForAcknowledgedHtmlReference(actions.readHtmlReference,{sourceSessionId:chat.body.sessionId,sourceRequestId:chat.body.requestId,sendOperationId:proposalId,messageId});
 const inbox=await actions.openOwnedInbox({control:'Reload',recipientId:merchant.persona.id,sourceEmailId:messageId});assert.equal(inbox.selectedMessage.body_markdown,body);const mounted=await actions.inspectLearnerElement({title:'V09 learner structural marker',subject,body,messageId});assert.equal(mounted.tag,'iframe');assert.equal(mounted.preserved,true);
 const assessment=await actions.assessHtml({reference:ready});assert.equal(assessment.response.value.completed,true);assert.equal(assessment.response.value.judgment.verdict,'pass');const canonical=await observe.readCanonical({assessment,chat,confirmation,mounted,original,objectiveId:OBJECTIVE});assert.equal(canonical.completed,true);assert.equal(canonical.durableProgress,true);
 const submitted=assertReference(await actions.readHtmlReference(),'submitted');for(const key of ['requestId','sourceSessionId','sourceRequestId','sendOperationId','messageId','startedAt'])assert.equal(submitted[key],ready[key]);await actions.reloadForRecovery({reference:submitted,messageId});const reloaded=assertReference(await actions.readHtmlReference(),'submitted');for(const key of ['requestId','sourceSessionId','sourceRequestId','sendOperationId','messageId','startedAt'])assert.equal(reloaded[key],ready[key]);const recovered=await actions.recoverHtml({reference:reloaded});assert.equal(recovered.response.value.replayed,true);assert.equal(recovered.response.value.judgment.evaluationId,assessment.response.value.judgment.evaluationId);
 const fixed=await guards.fixed({subject,body});assert.deepEqual(fixed,{modelChoice:true,ineligible:true,learnerElementPreserved:false,browserEffects:0,judgeCalls:0,credits:0,v61Credits:0});const sibling=await guards.sibling({ready,chat,confirmation});assert.deepEqual(sibling,{fixedSourceStatus:409,fixedAssessmentStatus:200,vulnerableAssessmentStatus:409,rowsUnchanged:true});const reset=await guards.reset({ready,assessment,canonical});assert.deepEqual(reset,{oldSourceStatus:401,oldAssessmentStatus:401,activeContributions:0,immutableHistory:true,siblingPreserved:true});const receipt=assertV09Receipt(await observe.finalize({fixed,sibling,reset,canonical}));return Object.freeze({actualQualification:true,objectiveId:OBJECTIVE,receipt,chat,confirmation,inbox,mounted,assessment,recovered,canonical,fixed,sibling,reset,bodySha256:createHash('sha256').update(body).digest('hex')});
}
module.exports={captureV09RequestBody,observeOriginalV09Json,validateOriginalV09Json,readOriginalV09Json,createCurrentHtmlReferenceReader,createV09AssessmentActions,V09_OBJECTIVE:OBJECTIVE,V09_FLAGS:FLAGS,V09_SCOPE:SCOPE,V09_BODY:BODY,assertReference,waitForAcknowledgedHtmlReference,runV09FixedGuardFlow,assertV09Receipt,runV09RenderedQualification};
